<?php
namespace ExcelHerbal\ERP7\Reporting;
use ExcelHerbal\ERP7\Database\Db;use ExcelHerbal\ERP7\Security\Actor;use ExcelHerbal\ERP7\Security\Capabilities;use ExcelHerbal\ERP7\Security\Guard;
final class ReportingService{
 public static function sales(Actor $a,int $branch,string $from,string $to):array{Guard::branch($a,$branch,Capabilities::REPORTS_VIEW);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT id,sale_no reference,DATE(sale_date) business_date,gross_amount,paid_amount,outstanding_amount,status FROM ".Db::table('counter_sales')." WHERE company_id=%d AND branch_id=%d AND DATE(sale_date) BETWEEN %s AND %s ORDER BY sale_date DESC,id DESC",$a->companyId,$branch,$from,$to),ARRAY_A);}
 public static function purchase(Actor $a,int $branch,string $from,string $to):array{Guard::branch($a,$branch,Capabilities::REPORTS_VIEW);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT b.*,s.name supplier_name FROM ".Db::table('purchase_bills')." b JOIN ".Db::table('suppliers')." s ON s.id=b.supplier_id WHERE b.company_id=%d AND b.branch_id=%d AND b.bill_date BETWEEN %s AND %s ORDER BY b.bill_date DESC,b.id DESC",$a->companyId,$branch,$from,$to),ARRAY_A);}
 public static function stock(Actor $a,int $branch):array{Guard::branch($a,$branch,Capabilities::REPORTS_VIEW);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT sb.*,p.sku,p.name product_name,b.batch_no,e.full_name custodian_name FROM ".Db::table('stock_balances')." sb JOIN ".Db::table('products')." p ON p.id=sb.product_id LEFT JOIN ".Db::table('batches')." b ON b.id=NULLIF(sb.batch_key,0) LEFT JOIN ".Db::table('employees')." e ON e.id=NULLIF(sb.custodian_key,0) WHERE sb.company_id=%d AND sb.branch_id=%d AND ABS(sb.quantity)>.0001 ORDER BY p.name,b.batch_no",$a->companyId,$branch),ARRAY_A);}
 public static function finance(Actor $a,int $branch,string $from,string $to):array{Guard::branch($a,$branch,Capabilities::REPORTS_VIEW);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT je.id,je.entry_no,je.entry_date,je.source_type,je.source_id,je.status,je.memo,SUM(jl.debit) debit,SUM(jl.credit) credit FROM ".Db::table('journal_entries')." je JOIN ".Db::table('journal_lines')." jl ON jl.journal_entry_id=je.id WHERE je.company_id=%d AND je.branch_id=%d AND DATE(je.entry_date) BETWEEN %s AND %s GROUP BY je.id ORDER BY je.entry_date DESC,je.id DESC",$a->companyId,$branch,$from,$to),ARRAY_A);}
 public static function trialBalance(Actor $a,string $to,?int $branch):array{Guard::cap($a,Capabilities::ACCOUNTING_VIEW);$db=Db::wpdb();$branchSql='';$args=[$to];if($branch){Guard::branch($a,$branch,Capabilities::ACCOUNTING_VIEW);$branchSql=' AND je.branch_id=%d';$args[]=$branch;}$args[]=$a->companyId;$sql="SELECT ac.id,ac.code,ac.name,ac.type,COALESCE(SUM(jl.debit),0) debit,COALESCE(SUM(jl.credit),0) credit,COALESCE(SUM(jl.debit-jl.credit),0) balance FROM ".Db::table('accounts')." ac LEFT JOIN ".Db::table('journal_lines')." jl ON jl.account_id=ac.id LEFT JOIN ".Db::table('journal_entries')." je ON je.id=jl.journal_entry_id AND je.status IN ('posted','reversed') AND DATE(je.entry_date)<=%s{$branchSql} WHERE ac.company_id=%d AND ac.active=1 GROUP BY ac.id ORDER BY ac.code";return(array)$db->get_results($db->prepare($sql,...$args),ARRAY_A);}
 public static function ledger(Actor $a,int $account,string $from,string $to,?int $branch):array{Guard::cap($a,Capabilities::ACCOUNTING_VIEW);$db=Db::wpdb();$sql="SELECT je.entry_no,je.entry_date,je.source_type,je.source_id,je.memo,jl.debit,jl.credit,jl.party_type,jl.party_id,jl.description FROM ".Db::table('journal_lines')." jl JOIN ".Db::table('journal_entries')." je ON je.id=jl.journal_entry_id WHERE je.company_id=%d AND jl.account_id=%d AND je.status IN ('posted','reversed') AND DATE(je.entry_date) BETWEEN %s AND %s";$args=[$a->companyId,$account,$from,$to];if($branch){Guard::branch($a,$branch,Capabilities::ACCOUNTING_VIEW);$sql.=' AND je.branch_id=%d';$args[]=$branch;}$sql.=' ORDER BY je.entry_date,je.id,jl.id';return(array)$db->get_results($db->prepare($sql,...$args),ARRAY_A);}
}
